<?php
require __DIR__.'/config.php';$me=require_auth();$cid=(int)$me['customer_id'];$uid=(int)$me['id'];$errors=[];$v=$_POST;
if($_SERVER['REQUEST_METHOD']==='POST'){
    check_csrf();$action=(string)($_POST['action']??'');$pdo=db();
    if($action==='block_request'){
        $cardId=filter_var($_POST['card_id']??null,FILTER_VALIDATE_INT);
        if(!$cardId)$errors[]='Select a valid card.';
        if(!$errors){try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT c.card_type,c.masked_number,c.status,a.account_id FROM cards c JOIN accounts a ON a.account_id=c.account_id JOIN account_holders h ON h.account_id=a.account_id WHERE c.card_id=? AND c.customer_id=? AND h.customer_id=? FOR UPDATE");$s->execute([(int)$cardId,$cid,$cid]);$card=$s->fetch();if(!$card||$card['status']!=='active')throw new RuntimeException();$staff=$pdo->query("SELECT DISTINCT u.user_id FROM users u JOIN user_roles ur ON ur.user_id=u.user_id JOIN roles r ON r.role_id=ur.role_id WHERE u.status='active' AND u.linked_employee_id IS NOT NULL AND r.role_name IN ('Employee','Administrator')")->fetchAll(PDO::FETCH_COLUMN);if(!$staff)throw new RuntimeException();$message=substr('Card block request: '.$me['name'].' asks to block the '.$card['card_type'].' card '.$card['masked_number'].'.',0,255);$add=$pdo->prepare("INSERT INTO notifications (user_id,type,message) VALUES (?,'card_block_request',?)");foreach(array_unique(array_map('intval',$staff)) as $staffId)$add->execute([$staffId,$message]);$pdo->prepare("INSERT INTO notifications (user_id,type,message) VALUES (?,'card_block_requested',?)")->execute([$uid,'Your request to block the '.$card['card_type'].' card '.$card['masked_number'].' was sent to staff.']);$pdo->commit();flash('Card block request sent to BankEase staff.');go('cards.php');}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$errors[]='The card block request could not be sent. Check the card status and try again.';}}
    }elseif($action==='card_request'){
        $accountId=filter_var($_POST['account_id']??null,FILTER_VALIDATE_INT);$cardType=(string)($_POST['card_type']??'');$limitRaw=trim((string)($_POST['credit_limit']??''));if(!$accountId||!owned_account($pdo,$cid,(int)$accountId))$errors[]='Choose one of your accounts.';if(!in_array($cardType,['debit','credit'],true))$errors[]='Choose a valid card type.';if($cardType==='credit'&&(!preg_match('/^\d{1,10}(\.\d{1,2})?$/',$limitRaw)||(float)$limitRaw<=0))$errors[]='Enter a requested credit limit for a credit card.';
        if(!$errors){try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT a.account_title,a.account_number,a.status FROM account_holders h JOIN accounts a ON a.account_id=h.account_id WHERE h.customer_id=? AND a.account_id=? FOR UPDATE");$s->execute([$cid,(int)$accountId]);$account=$s->fetch();if(!$account||$account['status']!=='active')throw new RuntimeException();$staff=$pdo->query("SELECT DISTINCT u.user_id FROM users u JOIN user_roles ur ON ur.user_id=u.user_id JOIN roles r ON r.role_id=ur.role_id WHERE u.status='active' AND u.linked_employee_id IS NOT NULL AND r.role_name IN ('Employee','Administrator')")->fetchAll(PDO::FETCH_COLUMN);if(!$staff)throw new RuntimeException();$requested=$cardType==='credit'?' Requested limit BDT '.number_format((float)$limitRaw,2).':'';$message=substr('Card request: '.$me['name'].' requested a '.$cardType.' card for '.$account['account_title'].' (account ending '.substr($account['account_number'],-4).').'.$requested,0,255);$add=$pdo->prepare("INSERT INTO notifications (user_id,type,message) VALUES (?,'card_request',?)");foreach(array_unique(array_map('intval',$staff)) as $staffId)$add->execute([$staffId,$message]);$customerMessage=substr('Your '.$cardType.' card request for account ending '.substr($account['account_number'],-4).' was sent to staff for review.',0,255);$pdo->prepare("INSERT INTO notifications (user_id,type,message) VALUES (?,'card_request_received',?)")->execute([$uid,$customerMessage]);$pdo->commit();flash('Card request sent to BankEase staff. You will receive an update here.');go('cards.php');}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Your card request could not be sent. Confirm the account is active and try again.';}}
    }else{$errors[]='Invalid card request.';}
}
$s=db()->prepare("SELECT a.account_id,a.account_title,a.account_number FROM account_holders h JOIN accounts a ON a.account_id=h.account_id WHERE h.customer_id=? AND a.status='active' ORDER BY a.account_id");$s->execute([$cid]);$accounts=$s->fetchAll();$s=db()->prepare('SELECT c.card_id,c.card_type,c.masked_number,c.credit_limit,c.issue_date,c.expiry_date,c.status,a.account_title,a.account_number FROM cards c JOIN accounts a ON a.account_id=c.account_id JOIN account_holders h ON h.account_id=a.account_id WHERE c.customer_id=? AND h.customer_id=? ORDER BY c.card_id DESC');$s->execute([$cid,$cid]);$cards=$s->fetchAll();render_start('Cards');?>
<section class="page-heading"><div class="eyebrow dark">Your BankEase cards</div><h1>Cards</h1><p>Review your cards or send staff a request to issue or block a card.</p></section><?php if($errors):?><div class="notice error" role="alert"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?>
<?php if($cards):?><div class="card-grid"><?php foreach($cards as $card):?><article class="customer-card"><div class="customer-card-top"><strong>BankEase</strong><span class="badge"><?=e(ucfirst($card['status']))?></span></div><p class="card-number"><?=e($card['masked_number'])?></p><div class="customer-card-bottom"><span><?=e(ucwords($card['card_type']))?> · <?=e($card['account_title'])?></span><span>Expires <?=e($card['expiry_date'])?></span></div><div class="card-details"><span>Issued <?=e($card['issue_date'])?></span><span>Credit limit <?=($card['credit_limit']===null?'—':'BDT '.e(number_format((float)$card['credit_limit'],2)))?></span><span>Account •••• <?=e(substr($card['account_number'],-4))?></span></div><?php if($card['status']==='active'):?><form method="post" class="block-card-form" onsubmit="return confirm('Send a request to staff to block this card?')"><?=csrf()?><input type="hidden" name="card_id" value="<?=$card['card_id']?>"><button class="text-button" type="submit" name="action" value="block_request">Request card block</button></form><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="empty">No cards are linked to your profile yet.</div><?php endif;?>
<section class="detail-card"><div class="eyebrow dark">Request a card</div><h2>Ask staff to issue a card</h2><p class="muted">A request goes to staff for review; it does not create or activate a card.</p><?php if(!$accounts):?><div class="empty">An active account is required to request a card.</div><?php else:?><form method="post" class="card-request-form"><?=csrf()?><input type="hidden" name="action" value="card_request"><div class="form-grid"><div class="field"><label for="account_id">Account</label><select id="account_id" name="account_id" required><option value="">Choose active account</option><?php foreach($accounts as $a):?><option value="<?=$a['account_id']?>" <?=((string)($v['account_id']??''))===(string)$a['account_id']?'selected':''?>><?=e($a['account_title'])?> · •••• <?=e(substr($a['account_number'],-4))?></option><?php endforeach;?></select></div><div class="field"><label for="card_type">Card type</label><select id="card_type" name="card_type" required><option value="debit">Debit</option><option value="credit" <?=($v['card_type']??'')==='credit'?'selected':''?>>Credit</option></select></div><div class="field credit-limit-field" hidden><label for="credit_limit">Requested credit limit (BDT)</label><input id="credit_limit" name="credit_limit" type="number" min="1" max="9999999999.99" step="0.01" value="<?=e($v['credit_limit']??'')?>" disabled></div></div><button class="button navy" type="submit">Send card request</button></form><?php endif;?></section><?php render_end();?>
